Data.DatabaseSchemes:
CREATE TABLE Criteria (
    criteria_id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    category VARCHAR(100) NOT NULL,
    weight DECIMAL(5,2) NOT NULL
);

CREATE TABLE CspProfiles (
    csp_profile_id UUID PRIMARY KEY,
    csp_name VARCHAR(255) NOT NULL,
    region VARCHAR(100),
    description TEXT
);

CREATE TABLE EvaluationResults (
    evaluation_id UUID PRIMARY KEY,
    criteria_id UUID REFERENCES Criteria(criteria_id),
    csp_profile_id UUID REFERENCES CspProfiles(csp_profile_id),
    score DECIMAL(5,2) NOT NULL,
    notes TEXT
);

Storage Tech Summary: PostgreSQL for relational data integrity and complex query capabilities, suitable for structured criteria, profiles, and evaluation results.
